export const ahmedijeSearch: { slug: string; chunks: { text: string; headingId: string; headingText: string }[] }[] = [{"slug":"Ahmedije-o-istini-Israa-i-Miradza","chunks":[{"text":"Kadijanski stav o Israu i Miradžu svodi se na dve tvrdnje: da je reč o dva odvojena događaja i da nisu bili telesni, nego duhovna vizija. Prva tvrdnja protivreči verodostojnim hadisima koji Isru i Miradž prenose kao jedan događaj. Druga protivreči jasnom značenju kur'anskih ajeta, jer se veličanje izriče samo za velike stvari, a u pukom snoviđenju nema ničeg izuzetnog. Reč „rob\" obuhvata i dušu i telo, a pogled je oruđe tela, ne duše. Sve to pokazuje da su Isra i Miradž bili i dušom i telom. Reči kadijanaca, preuzete od njihovog drugog kalife, mogu se sažeti u dve tačke: 1. Isra i Miradž su dva odvojena događaja. 2. Isra i Miradž nisu bili telesni, nego duhovna objava. Te dve","headingId":"","headingText":""},{"text":"tačke predstavljaju vrlo star spor o ovom pitanju. Mali broj prethodnika i potonjih učenjaka to je tvrdio, i time su se suprotstavili istini i mišljenju većine. Kadijanci su prihvatili to mišljenje zato što gaje strast prema pretvaranju svakog kur'anskog čuda u snoviđenje, uključujući i kazivanje o Musau, mir neka je na njega, i Hidru, kao i kazivanje o Musaovom štapu i slično. To mišljenje su prihvatili samo da bi odbranili činjenicu da u Mirzinom tobolcu nema nijednog stvarnog dokaza koji bi potkrepio njegove tanke tvrdnje.","headingId":"","headingText":""},{"text":"Prva tačka Isra i Miradž kao dva odvojena događaja Što se tiče prve tačke, u njoj i nema mnogo neobičnog, ali se odbacuje zato što protivreči verodostojnim hadisima koji Isru i Miradž spominju kao jedan događaj. Među njima je i ono što u svom Sahihu prenosi Buhari, kao i drugi: Allahov Poslanik ﷺ im je pripovedao o noći u kojoj je prenesen: Bio sam u Hatimu, a možda je rekao u Hidžru, i ležao sam, kada mi je neko došao i rasporio me od grla do stomaka. Izvadio mi je srce. Zatim mi je donesena zlatna posuda ispunjena verom, pa mi je srce oprano, potom ispunjeno i vraćeno na svoje mesto. Zatim mi je dovedena životinja manja od mazge, a","headingId":"prva-tacka-isra-i-miradz-kao-dva-odvojena-dogadjaja","headingText":"Prva tačka - Isra i Miradž kao dva odvojena događaja"},{"text":"veća od magarca, bele boje. To je Burak. Korak joj dopire dokle joj seže pogled. Bio sam uzjahan na nju i ona je krenula sa mnom, a Džibril je išao sa mnom, sve dok nije stigao do najnižeg neba i zatražio dozvolu. Upitano je: Ko je to? Rekao je: Džibril. Upitano je: Ko je sa tobom? Rekao je: Muhammed. Upitano je: Zar mu je već poslato? Rekao je: Da. Rečeno je: Dobro nam došao, divnog li dolaska! Zatim je otvoreno. Kada sam ušao, u njemu je bio Adem. Rečeno mi je: Ovo je tvoj otac Adem, poselami ga. Poselamio sam ga, a on je uzvratio selam i rekao: Dobro došao, čestiti sine i čestiti poslaniče. Zatim se sa mnom uspeo","headingId":"prva-tacka-isra-i-miradz-kao-dva-odvojena-dogadjaja","headingText":"Prva tačka - Isra i Miradž kao dva odvojena događaja"},{"text":"do drugog neba. Izvor: Buhari.","headingId":"prva-tacka-isra-i-miradz-kao-dva-odvojena-dogadjaja","headingText":"Prva tačka - Isra i Miradž kao dva odvojena događaja"},{"text":"Druga tačka tvrdnja da Isra i Miradž nisu bili telesni Druga tačka se odbacuje zato što protivreči jasnom značenju plemenitih ajeta. Sura El Isra 17:1 Uzvišen neka je Onaj Koji je u jednom času noći preveo Svog slugu Muhammeda od Časne džamije do Daleke džamije.. Veličanje se izriče samo za velike stvari, a u snoviđenju nema ničeg izuzetnog. Zatim, Njegove reči „Svoga roba\" jasan su dokaz da je putovanje bilo i dušom i telom, jer je rob spoj duše i tela. Sura En Nedžm 53:17 pogled mu nije skrenuo i nije prekoračio. I ovo je jasan dokaz da je putovanje bilo telesno, jer je pogled oruđe tela, a ne duše.","headingId":"druga-tacka-tvrdnja-da-isra-i-miradz-nisu-bili-telesni","headingText":"Druga tačka - tvrdnja da Isra i Miradž nisu bili telesni"},{"text":"Kadijansko shvatanje objave Kadijanci su pokušali da objavu prikažu kao natprirodnu pojavu, pa su rekli: Objava ili viđenje… dešava se odabranoj osobi dok je u stanju potpune budnosti… ona vidi stvar i svesna je događaja objave… sama u osami, daleko od ljudi, ili pred ljudima, a oni ne znaju šta se sa njom dešava, ili pred ljudima i sa njima, tako da i oni u tome učestvuju. Kažem: ne znam u čemu je velika razlika između snova i budnih maštanja. Zar dokazivanje da su Isra i Miradž bili budna maštanja opravdava to što su nevernici poricali taj događaj? Prianjanje uz ovako slabe dokaze pokazuje da ti ljudi nemaju ni šerijatskog ni razumskog dokaza. Još je gore njihovo nabrajanje vrsta duhovne","headingId":"kadijansko-shvatanje-objave","headingText":"Kadijansko shvatanje objave"},{"text":"objave, kao da ih je Uzvišeni Allah obavestio o njenim pojedinostima. Tvrde da je događaj u kojem se Džibril, mir neka je na njega, pojavio u ljudskom liku i postavio pitanje o imanu, islamu i ihsanu bio zajednička objava koju su Poslanik ﷺ i ashabi videli zajedno. Isto tako tvrde da je kazivanje o Musau, mir neka je na njega, i Hidru vremenska objava koju je Musa video, pa da je Musaov mladić Isa, mir neka je na njega, a Hidr Muhammed ﷺ. Kažem: ovako smešna tumačenja dovoljan su dokaz batinijstva ove kadijanske sekte i njene nepripadnosti islamu.","headingId":"kadijansko-shvatanje-objave","headingText":"Kadijansko shvatanje objave"},{"text":"Mešanje verodostojnih, slabih i izmišljenih hadisa Ono što se u kadijanskim tumačenjima uopšte primećuje jeste njihovo mešanje verodostojnih, slabih i izmišljenih hadisa, te korišćenje bilo kojeg dokaza koji im odgovara. Ne vide nikakvu smetnju u tome da odbace jasno značenje verodostojnog hadisa samo zato što protivreči izmišljenom hadisu ili predanju. To pokazuje da tim ljudima nije stalo do spoznaje istine, nego do dokazivanja onoga za čim žude njihove bolesne duše i nezdravi umovi. Primećuje se i da su zbunjeni u svojim dokazima i tumačenjima. Tako, na primer, u tumačenju Mesdžidul aksaa u ajetu o Israu, nalazimo da spajaju tri tumačenja odjednom: 1. Mesdžidul aksa je Poslanikova ﷺ džamija u Medini, pa kažu: „Zato ju je Bog nazvao… to jest Medinu…","headingId":"mesanje-verodostojnih-slabih-i-izmisljenih-hadisa","headingText":"Mešanje verodostojnih, slabih i izmišljenih hadisa"},{"text":"Mesdžidul aksa po svetosti i blagoslovu.\" 2. Mesdžidul aksa je Jerusalim. Kažu: „Mesdžidul aksa se odnosi i na sam Jerusalim.\" 3. Mesdžidul aksa je džamija onog čoveka u Kadijanu. Kažu: „Ovo, i Poslanikovo ﷺ noćno putovanje do Mesdžidul aksaa, ukazuje i na to da će, kada snaga islama oslabi i kada zemlju prekrije tama napuštanja Allahove Knjige, Njegove vere i Njegovog zakona, i kada muslimani sami sebe bace pod vlast krstaškog Zapada… blagoslovi Odabranog ﷺ poteći ka jednom čoveku iz njegovog ummeta… tamo, u najudaljenijim krajevima islama…\", sve do reči: „I pokazaće se slava i mudrost Uzvišenog Allaha u oživljavanju i obnavljanju islama blagoslovom Muhammeda ﷺ u njegovoj drugoj misiji, i to rukama imama Mehdija i Obećanog Mesije.\" U trećoj","headingId":"mesanje-verodostojnih-slabih-i-izmisljenih-hadisa","headingText":"Mešanje verodostojnih, slabih i izmišljenih hadisa"},{"text":"tački kadijanci su pokušali da uvrste tumačenje svog lažnog predvodnika o tome šta se misli pod Mesdžidul aksaom u suri El Isra, jer on u svojoj knjizi Nadahnuta hutba kaže sledeće: Što se tiče prve i druge tačke sa početka izlaganja, ne vidim potrebu da se na njima zadržavam u odgovoru ahmedijama, jer to nisu odlike samo ahmedija. Neki su to govorili i pre i posle njih.","headingId":"mesanje-verodostojnih-slabih-i-izmisljenih-hadisa","headingText":"Mešanje verodostojnih, slabih i izmišljenih hadisa"}]},{"slug":"Bogohulstvo-Mirze-Gulama-Kadijanija-njegovim-recima-Kufr-lazno-prorocanstvo-i-kadijanska-tvrdnja-razotkriveni","chunks":[{"text":"Svako stvorenje bez izuzetka pred Allaha izlazi isključivo kao rob. Ne kao sin. Ne kao sudrug. Ne kao jedinstvo. Ne kao odraz Njegove božanstvenosti. To je tevhid koji je Mirza Gulam razbio sopstvenim rečima, u sopstvenim knjigama, kroz decenije pisanja. Mirza Gulam Kadijani, osnivač kadijanskog pokreta, nije optužen za bogohulstvo na osnovu tuđih tvrdnji ili neprijateljskih svedočanstava. Njegove sopstvene knjige, objavljivane tokom decenija i sačuvane u zbirci Ruhani Hazain, sadrže izjave koje same po sebi predstavljaju napuštanje islamskog monoteizma. U nastavku se izlažu ti tekstovi redom, uz izvorne stranice, a zatim i kur'anski odgovor na sam pojam pripisivanja sina Allahu.","headingId":"","headingText":""},{"text":"Tvrdnja o božanskom sjedinjenju — Ruhani Hazain, tom 13","headingId":"tvrdnja-o-bozanskom-sjedinjenju-ruhani-hazain-tom-13","headingText":"Tvrdnja o božanskom sjedinjenju — Ruhani Hazain, tom 13"},{"text":"Izvor 1 — tom 13, str. 100 Sledeća slika preuzeta je iz Ruhani Hazaina, tom 13, str. 100, gde Mirza Gulam navodi „nadahnuće\" koje tvrdi da je primio od Boga. Tako je i ovaj ponizni čuo u svojim božanskim nadahnućima od Boga: „Ti si od Mene i Ja sam od tebe.\" Ova nadahnuća objavio sam u svojim knjigama „Berahin i Ahmedija\", „Aina i Kemalat i Islam\", „Izala i Evham\" i „Tuhfa i Bagdad\", i drugim, i objavljujem ih već skoro 25 godina. Sam Mirza Gulam potvrđuje da ovo nije usamljena ili slučajno zabeležena izjava. On izričito navodi da je ista tvrdnja objavljivana u više njegovih knjiga tokom perioda od skoro 25 godina, što isključuje mogućnost da je reč o omašci","headingId":"izvor-1-tom-13-str-100","headingText":"Izvor 1 — tom 13, str. 100"},{"text":"ili o iskrivljenom prenošenju.","headingId":"izvor-1-tom-13-str-100","headingText":"Izvor 1 — tom 13, str. 100"},{"text":"Izvor 2 — tom 13, str. 101 Sledeća slika je sa naredne stranice istog toma, gde se jezik tvrdnje dodatno pooštrava. Ja sam od tebe, i nebesa i Zemlja su sa tobom, kao što su i sa Mnom. Ti si od Moje vode, a ostali su od zemlje. Ti si Meni blizak kao Moje jedinstvo, i ti si sa Mnom u jedinstvu koje nijedno stvorenje ne poznaje. (…) Ti si večna Reč, zato nećeš biti izbrisan. (…) Ti si svetlost sveta. Ključna rečenica glasi: „Ti si Meni blizak kao Moje jedinstvo, i ti si sa Mnom u jedinstvu koje nijedno stvorenje ne poznaje.\" Time se između Boga i stvorenja uspostavlja odnos jedinstva, a upravo taj odnos islamski monoteizam isključuje. Da","headingId":"izvor-2-tom-13-str-101","headingText":"Izvor 2 — tom 13, str. 101"},{"text":"li Mirza ovde stvara sopstveni novi oblik mnogoboštva i raskida sa tevhidom?","headingId":"izvor-2-tom-13-str-101","headingText":"Izvor 2 — tom 13, str. 101"},{"text":"Mirza se ugleda na Bibliju — Jovan 1 Formulacije „večna Reč\" i „svetlost sveta\" nisu kur'anske. One pripadaju uvodu Jovanovog jevanđelja. Jovan 1:1–4 1. U početku je bio On – Reč, i On – Reč je bio sa Bogom. On – Reč bio je Bog. 2. On je u početku bio sa Bogom. 3. Sve je njegovim posredstvom postalo i ništa što je postalo nije postalo bez njega. 4. U Reči je bio život i taj život je bio svetlost ljudima. Uporedi jezik Mirzinog takozvanog „nadahnuća\". Pozajmljivanje je očigledno i neosporno.","headingId":"mirza-se-ugleda-na-bibliju-jovan-1","headingText":"Mirza se ugleda na Bibliju — Jovan 1"},{"text":"Eksplicitna izjava — tom 13, str. 104 Nekoliko stranica kasnije Mirza Gulam Kadijani daje eksplicitnije objašnjenje koje ne zahteva nikakav dodatni komentar. U međuvremenu sam video da me je Allahov Duh obavio i zagospodario mojim telom, sakrivši me u sebe, sve dok od mene nije ostala nijedna čestica. Kada sam pogledao svoje telo, video sam da su moji udovi Njegovi udovi, i moje oči Njegove oči, i moje uši Njegove uši, i da je moj jezik postao Njegov jezik. Moj Gospodar me je uzeo i držao me tako čvrsto da sam se potpuno izgubio u Njemu. Video sam kako Njegova moć i snaga rastu u meni, i kako je Njegova božanstvenost (al uluhijja) proticala kroz mene. Al uluhijja označava Allahovu","headingId":"eksplicitna-izjava-tom-13-str-104","headingText":"Eksplicitna izjava — tom 13, str. 104"},{"text":"jedinstvenost i Njegovo isključivo pravo da bude obožavan. Prema rečima Mirze Gulama, dakle, kroz Mirzu Gulama je proticalo „Allahovo pravo da bude obožavan\".","headingId":"eksplicitna-izjava-tom-13-str-104","headingText":"Eksplicitna izjava — tom 13, str. 104"},{"text":"Dodatna bogohulstva ostali izvori","headingId":"dodatna-bogohulstva-ostali-izvori","headingText":"Dodatna bogohulstva - ostali izvori"},{"text":"Hakikatul vahj, str. 912 sin Božiji Ti si Meni kao Moj sin.","headingId":"hakikatul-vahj-str-912-sin-boziji","headingText":"Hakikatul-vahj, str. 912 - sin Božiji"},{"text":"Ruhani Hazain, tom 22, str. 581 — dete Božije Babu Elahi Bakš želi da vidi tvoju menstruaciju ili da na tebi pronađe neku nečistoću ili prljavštinu, ali Svemogući Bog će ti ukazati Svoju naklonost, koja će biti česta, i ti nećeš imati menstruaciju, nego će se roditi dete, dete koje je dete Božije. Pored samog po sebi neobičnog „nadahnuća\" u kojem se Mirzi saopštava da neće imati menstruaciju — što je za muškarca ionako nemoguće — vidimo da on izraz „sin Božiji\" koristi više puta u svojim knjigama, zajedno sa drugim sličnim „izjavama\".","headingId":"ruhani-hazain-tom-22-str-581-dete-bozije","headingText":"Ruhani Hazain, tom 22, str. 581 — dete Božije"},{"text":"Ruhani Hazain, tom 21, str. 81 — skriveni odnos Ja imam skriveni odnos sa Bogom koji se ne može izraziti rečima. Ljudi ovog vremena toga nisu svesni.","headingId":"ruhani-hazain-tom-21-str-81-skriveni-odnos","headingText":"Ruhani Hazain, tom 21, str. 81 — skriveni odnos"},{"text":"Islami kurbani — „žensko\" nadahnuće Jednom prilikom je hazreti Mesih i Mev'ud (Mirza Gulam Kadijani) otkrio svoje stanje, navodeći da ga je stanje nadahnuća obuzelo tako da se osećao kao da je žena i kao da je Allah kroz njega izrazio Svoju mušku moć. Ovaj nagoveštaj je dovoljan onima koji mogu da razumeju. Izvor: Islami kurbani, Kazi Jar Muhammed, str. 12. Ovim besmislicama nema šta da se doda.","headingId":"islami-kurbani-zensko-nadahnuce","headingText":"Islami kurbani — „žensko\" nadahnuće"},{"text":"Tri značenja reči „sin\" — i zašto su sva opovrgnuta Slično tvrdnji hrišćana da je Bog uzeo sina, reč „sin\" može imati samo tri moguća značenja: 1. Biološki sin 2. Usvojeni sin 3. Metaforički sin Budući da značenja 1 i 2 odbacuju i hrišćani i kadijanci — jer im je preostalo dovoljno razuma da zaključe da Bog niti biološki rađa niti usvaja tuđeg sina — preostaje jedino metaforičko značenje . Međutim, Allah u Kur'anu ne pravi razliku između tih značenja. Izraz „sin\" se islamski ne sme pripisati Allahu ni na koji način: ni biološki, ni usvojenjem, ni metaforički.","headingId":"tri-znacenja-reci-sin-i-zasto-su-sva-opovrgnuta","headingText":"Tri značenja reči „sin\" — i zašto su sva opovrgnuta"},{"text":"Kur'anska presuda — sura Merjem 19:88–93 Sura Merjem, 19:88–93 1. Oni govore: „Svemilosni je uzeo dete!“ 2. Vi, zaista, govorite nešto strašno i gnusno! 3. Gotovo da se od toga nebesa raspadnu, a Zemlja provali i planine zdrobe, 4. jer Svemilosnom pripisuju dete! 5. Nezamislivo je da Svemilosni ima dete!","headingId":"kuranska-presuda-sura-merjem-198893","headingText":"Kur'anska presuda — sura Merjem 19:88–93"}]},{"slug":"Da-li-ce-Mirza-doci-ponovo","chunks":[{"text":"Mirza Gulam Kadijani je sam sebi postavio uslov. Cilj zbog kojeg je, kako tvrdi, došao jeste da slomi stub obožavanja Isaa, a ako taj cilj ne ostvari, onda je, po sopstvenim rečima, lažov, makar se od njega pojavio i milion znakova. Umro je 1908. godine, a obožavanje Isaa i danas traje. Uz to, njegovi tekstovi protivreče jedni drugima: na jednom mestu najavljuje da će Isaova duhovnost sići tri puta, dakle i posle njega, a na drugom tvrdi da je on poslednji dolazak bilo kakvog mesije. U kadijanskim spisima nalazi se najava koja sama po sebi ruši Mirzinu tvrdnju: ako je on bio drugi dolazak Isaa, čemu onda treći? Nastupiće razdoblje monoteizma, ali će se potom u svet vratiti pokvarenost, mnogoboštvo","headingId":"","headingText":""},{"text":"i nasilje. Ljudi će proždirati jedni druge poput insekata, neznanje će zagospodariti, a obožavanje Isaa će se ponovo pojaviti. Bezumlje pobožanstvenjivanja stvorenja široko će se raširiti. Sva ta pokvarenost poteći će iz hrišćanske religije u završnoj fazi poslednjeg doba. Tada će duhovnost onoga koji nije Mesija snažno poželeti da siđe u veličanstvu. Pojaviće se u liku blistavog bića da okonča to doba. Zatim će doći kraj i svet će biti smotan. Ovo jasno pokazuje da je zbog nedostojnih dela Isaovih sledbenika određeno da Isaova duhovnost siđe tri puta u svet. Izvor: Maktubat i Ahmedija, tom 5, broj 4, str. 43. To znači da je Isa prvi put došao poslat sinovima Israilovim, da se drugi dolazak, navodno, dogodio rođenjem Mirze, a","headingId":"","headingText":""},{"text":"da je sada, po svemu sudeći, potreban i treći put.","headingId":"","headingText":""},{"text":"Uslov koji je Mirza sam postavio Moja misija, zbog koje stojim na bojnom polju, jeste da slomim stub obožavanja Isaa. I da umesto trojstva raširim tevhid, i da svetu pokažem veličinu i slavu poslanika Muhammeda ﷺ. Pa čak i ako se od mene pojavi milion znakova, a taj KRAJNJI CILJ ne bude ostvaren, onda sam lažov. Zašto mi je onda svet neprijatelj, zašto ne sačeka moj kraj? Ako sam za islam učinio ono što treba da učini Obećani Mesija i Mehdi zaveta, onda sam istinit. A ako se to ne ostvari, pa ja umrem, neka svi budu svedoci da sam lažov. Mirza Gulam, dakle, sam utvrđuje da je cilj i svrha drugog dolaska Mesije, za kojeg tvrdi da je on","headingId":"uslov-koji-je-mirza-sam-postavio","headingText":"Uslov koji je Mirza sam postavio"},{"text":"lično, to da se „slomi krst\" prekidanjem obožavanja Isaa. Ako to ne ispuni za života, dokazano je da je lažov, makar sa sobom doneo bilo koliko znakova. Ne treba ni napominjati da i danas možemo posmatrati obožavanje Isaa.","headingId":"uslov-koji-je-mirza-sam-postavio","headingText":"Uslov koji je Mirza sam postavio"},{"text":"Protivrečnost u sopstvenim spisima S druge strane, nalazimo Mirzine navode koji tome protivreče, u kojima tvrdi da je on poslednji dolazak bilo kakvog mesije.","headingId":"protivrecnost-u-sopstvenim-spisima","headingText":"Protivrečnost u sopstvenim spisima"}]},{"slug":"Da-li-je-Mirza-Kadijani-znao-ista-o-Allahovom-Poslaniku","chunks":[{"text":"Mirza Gulam Ahmed Kadijani je napisao da je Poslanikov ﷺ otac umro nekoliko dana nakon njegovog rođenja i da mu je majka umrla ostavivši za sobom odojče staro svega nekoliko meseci. Poznata sira svedoči drugačije: Abdullah je umro pre Poslanikovog ﷺ rođenja, a Amina je umrla kada je imao oko šest godina. To ne tvrde samo protivnici kadijanaca, nego i knjiga njihovog drugog kalife, koja izričito navodi šestu godinu Poslanikovog ﷺ života i smrt njegove majke u Ebvi. Osnovni podaci iz Poslanikovog ﷺ života spadaju u znanje koje se ne propušta. Utoliko je značajnije ono što je o tome zapisao čovek koji je tvrdio da prima objavu od Boga.","headingId":"","headingText":""},{"text":"Mirzina izjava Pogledajte istoriju, videćete da je Njegova svetost Poslanik ﷺ bio ono siroče čiji je otac umro nekoliko dana nakon njegovog rođenja, i čija je majka umrla ostavivši za sobom sina odojče, starog svega nekoliko meseci. Izvor: Ruhani Hazain, tom 23, knjiga Pejgam i sulh, str. 465. Sken je iz Ruhani Hazaina, tom 23, Pejgam i sulh, str. 465. Označeni odlomak na urdu jeziku sadrži izjavu Mirze Gulama Ahmeda Kadijanija o ranom životu poslanika Muhammeda ﷺ: da je bio siroče čiji je otac umro samo nekoliko dana nakon njegovog rođenja i čija je majka umrla ostavivši sina odojče starog svega nekoliko meseci.","headingId":"mirzina-izjava","headingText":"Mirzina izjava"},{"text":"U čemu je problem Ova izjava se sukobljava sa opštepoznatim kazivanjem sire. Poslanikov ﷺ otac Abdullah umro je pre njegovog rođenja, a ne nekoliko dana posle njega. Njegova majka Amina umrla je kada je Poslanik ﷺ imao oko šest godina, a ne kada je bio odojče od nekoliko meseci. Zašto onda kadijanci nisu poverovali ovom podatku koji im je dao njihov prvak iz Kadijana? Ili možda, po svom običaju, ipak ne veruju vestima koje im je doneo njihov navodni poslanik?","headingId":"u-cemu-je-problem","headingText":"U čemu je problem"},{"text":"Knjiga drugog kadijanskog kalife Jasno je da je drugi kalifa zaobišao nadahnuća svoga oca, čoveka koji je bolovao od hipohondrije. Sken prikazuje korice arapske knjige Život Muhammeda i stranu 7 istog dela. Knjiga se pripisuje Mirzi Bešir ud dinu Mahmudu Ahmedu, drugom kadijanskom kalifi. Označeni odlomak na arapskom navodi da je u šestoj godini Poslanikovog ﷺ života njegova majka pošla sa njim u Medinu da poseti svoju rodbinu po majčinoj strani. Na povratku ka Meki zaustavili su se u Ebvi, gde je Amina, Poslanikova ﷺ majka, umrla. Odlomak zatim navodi da je Umm Ejmen vratila Poslanika ﷺ njegovom dedi Abdul Muttalibu. Taj sken izravno protivreči izjavi pripisanoj Mirzi Gulamu Ahmedu Kadijaniju. Mirza je rekao da je Poslanikova ﷺ majka umrla","headingId":"knjiga-drugog-kadijanskog-kalife","headingText":"Knjiga drugog kadijanskog kalife"},{"text":"kada je bio star svega nekoliko meseci, dok knjiga samog drugog kadijanskog kalife navodi da je Amina umrla kada je Poslanik ﷺ imao šest godina.","headingId":"knjiga-drugog-kadijanskog-kalife","headingText":"Knjiga drugog kadijanskog kalife"},{"text":"Zaključak 1. Mirza Gulam Ahmed Kadijani tvrdio je da je Poslanikova ﷺ majka umrla kada je bio star svega nekoliko meseci. 2. Knjiga samog drugog kadijanskog kalife navodi da je Poslanikova ﷺ majka umrla kada je imao šest godina. Pitanje, dakle, ostaje: da li je Mirza Kadijani poznavao osnove sire, ili su njegovu obavest kasnije odbacili njegovi sopstveni sledbenici?","headingId":"zakljucak","headingText":"Zaključak"}]},{"slug":"Da-li-je-Mirza-sin-Merjemin","chunks":[{"text":"Poslanik ﷺ se zakleo Allahom da će među ovaj ummet sići Isa, sin Merjemin. Taj izraz zatvara svaka vrata svakome ko nije stvarni, biološki sin Merjemin. Mirza Gulam Kadijani je znao da ne može tvrditi da ga je rodila Merjema, pa je sve pretvorio u metaforu i ustvrdio da ga je Bog nazvao „Merjem\" i da je „metaforički\" zatrudneo. Pritom je sam pisao da zakletva u proročanstvu znači da se ono mora uzeti u doslovnom smislu, bez tumačenja i bez izuzetka. Tim pravilom je oborio sopstvenu tvrdnju. Poslanik Muhammed ﷺ kune se Allahom da će Isa, sin Merjemin, biti onaj koji će sići među ovaj ummet. Tako mi Onoga u čijoj je ruci moja duša, uskoro će se među vama","headingId":"","headingText":""},{"text":"spustiti sin Merjemin kao pravedan sudija. Slomiće krst, ubiće svinju, ukinuće džizju, a imetka će biti toliko da ga niko neće prihvatati. Izvor: Buhari, 3448; Muslim, 155. Ono što ovom hadisu i njegovoj formulaciji daje težinu jeste upotreba izraza „sin Merjemin\". Time se automatski isključuje svako ko tvrdi da je Isa, a nije stvarni, biološki sin Merjemin. To je jedna od mudrosti koje vidimo u izboru reči u Kur'anu i u Poslanikovim ﷺ rečima zabeleženim u hadisima. Poslanik Isa se na jedinstven način naziva „sinom Merjeminim\", čime se ne ostavlja nikakva mogućnost da neko drugi tvrdi da je drugi dolazak Isaa niti da se to proročanstvo ispuni na bilo koji drugi način osim doslovnog: dolaskom sina Merjeminog, što nužno znači","headingId":"","headingText":""},{"text":"da je zaista reč o sinu Merjeminom. Sa tim problemom suočio se i sam Mirza. Znao je da ne može tvrditi da je bukvalno rođen od Merjeme, koja je odavno preminula, jer bi to svako odmah primetio.","headingId":"","headingText":""},{"text":"Mirzin odgovor na ovaj argument Mirza je na ovaj argument dao odgovor. Mirzi ne preostaje ništa drugo nego da to izvrne u metaforu i da tvrdi da ga je Bog nazvao „Merjem\", preuzimajući pritom reči iz sure Ez Zuhruf. Sura Ez Zuhruf 43:70 „Uđite u Raj, vi i vaše supruge, radosni!“","headingId":"mirzin-odgovor-na-ovaj-argument","headingText":"Mirzin odgovor na ovaj argument"},{"text":"Metaforička trudnoća Mirza Gulam je kasnije tvrdio da je „metaforički\" zatrudneo. Dve godine sam ostao othranjivan u svojstvu Merjeme, rastući pod zastorom. Zatim, kada su te dve godine prošle, kako je zabeleženo u Berahin i Ahmediji, četvrti deo, str. 496, u mene je udahnut duh Isaov, kao što je udahnut u Merjemu, i metaforički sam proglašen trudnim. I najzad, nakon nekoliko meseci, ali ne više od deset meseci, kroz onu objavu koja je poslednja zabeležena u Berahin i Ahmediji, četvrti deo, str. 556, pretvoren sam iz Merjeme u Isaa. Na taj način sam, dakle, postao sin Merjemin. Izvor: Ruhani Hazain, tom 19, str. 50. Ni sve to ga, međutim, ne čini Isaom, sinom Merjeminim.","headingId":"metaforicka-trudnoca","headingText":"Metaforička trudnoća"},{"text":"Mirzino sopstveno pravilo zakletva znači doslovno značenje Osim toga, Mirza Gulam smatra da se svako proročanstvo koje sadrži zakletvu mora uzeti doslovno. A zakletva jasno pokazuje da se ovo proročanstvo mora uzeti u svom doslovnom smislu. U njemu nema ni tumačenja ni izuzetka. U protivnom, čemu bi zakletva uopšte služila? Izvor: Hamamat el bušra, str. 49. Vratimo se sada hadisu. U njemu se Poslanik Muhammed ﷺ kune Allahom da je upravo Isa, sin Merjemin, onaj koji će sići među ovaj ummet. Uzeti to proročanstvo doslovno znači da Isa, sin Merjemin, iz tog hadisa može biti jedino onaj istorijski, biološki sin Merjemin, poslat sinovima Israilovim pre oko dve hiljade godina.","headingId":"mirzino-sopstveno-pravilo-zakletva-znaci-doslovno-znacenje","headingText":"Mirzino sopstveno pravilo - zakletva znači doslovno značenje"}]},{"slug":"Karakter-Mirze-Gulama-Kadijanija","chunks":[{"text":"Mirza Gulam Kadijani je biblijskog Isaa prekorevao zato što nije postupao po sopstvenom moralnom učenju, ističući da je vređao jevrejske starešine i nazivao ih nezakonitom decom. U svojim knjigama je, međutim, sam protivnike nazivao kopiladima, potomstvom bludnica i najprostijim izrazima, i to pišući kao neko ko tvrdi da je poslanik i mesija koji svoje učenje prima od Boga. Merilo koje je postavio drugima obara njegov sopstveni položaj. Učitelj morala mora prvi pokazati taj moral na sebi. To pravilo nije naše, nego Mirzino. U nastavku se navode njegove sopstvene reči, redom i uz izvore. Navodi koji slede prenose se doslovno iz Mirzinih knjiga i sadrže vulgarne i uvredljive izraze. Prenose se isključivo radi dokumentovanja onoga što je napisao.","headingId":"","headingText":""},{"text":"Izraz „haramzade\" Ruhani Hazain, tom 10, str. 63 U jednom od svojih spisa Mirza Gulam koristi izraz „haramzade\" da bi uvredio Arja Samadž, hinduistički reformski pokret. Prevod glasi: Prvo navedite tačna i verodostojna upućivanja iz onih knjiga koje se smatraju pouzdanim, pa tek onda iznosite primedbe. U protivnom, nepravednim omalovažavanjem svete ličnosti ne razotkrivajte svoju gnusnu i nisku prirodu. Kada razmislimo o tome zašto takva gnusna kopilad (haramzade), niski neprijatelji po prirodi, lažno optužuju svete i voljene robove Uzvišenog Boga, na pamet ne pada nijedan razlog osim toga da Uzvišeni Bog želi da pokaže nečistu suštinu tame nasuprot svetlosti. Izvor: Ruhani Hazain, tom 10, str. 63. Pogledajmo sada kako se ta reč razume, i po definiciji i kod drugih ljudi.","headingId":"izraz-haramzade-ruhani-hazain-tom-10-str-63","headingText":"Izraz „haramzade\" - Ruhani Hazain, tom 10, str. 63"},{"text":"Pesma upućena Arja Samadžu Ruhani Hazain, tom 10, str. 76 Sledeći odlomak je pesma Mirze Gulama Kadijanija, takođe upućena Arja Samadžu, odnosno hinduističkom reformskom pokretu. Zaluđeni su tuđim ženama, njihovi muževi zaslužuju da budu spaljeni. Koga god da vidiš, on je lovac, a svaka njihova žena je bludnica. Prositi seme od tuđih muškaraca, kakve li divne vere, kakvog li verovanja, u kojem je blud obavezan. Arijci! Duboko razmislite u svojim srcima, gde vam je stid i čast? Ono što se kod Arijaca zove nijog jeste testera koja odseca nos. Ti bestidni neprijatelji ne misle ništa, nego da je to skriveno prijateljstvo. Onaj ko se time bavi veliki je podvodač, a verovati u to loše je ponašanje. Velika je to ljubav","headingId":"pesma-upucena-arja-samadzu-ruhani-hazain-tom-10-str-76","headingText":"Pesma upućena Arja Samadžu - Ruhani Hazain, tom 10, str. 76"},{"text":"i zloba, kada neko spava sa strancem: ona nije supruga, nego bludnica. Ona je Čandal, prezrena i grešna, a njen partner je Čamari. Milioni su deca nijoga, i to poniženje postoji u zemlji Arijaca. Neka je Božije prokletstvo na takvu decu, to nisu deca, nego Božije kazne. Sve se to čini u ime rađanja dece, a čitava ta pometnja je polna požuda. Izvor: Ruhani Hazain, tom 10, str. 76.","headingId":"pesma-upucena-arja-samadzu-ruhani-hazain-tom-10-str-76","headingText":"Pesma upućena Arja Samadžu - Ruhani Hazain, tom 10, str. 76"},{"text":"Et teblig prva arapska knjiga Reč je o delu Et teblig, prvoj arapskoj knjizi Mirze Gulama i njegovih saradnika. Svaki musliman će me prihvatiti i potvrdiće moju tvrdnju, osim zurrijjetul begaja (potomstva bludnica), čija je srca Uzvišeni Bog zapečatio. Izvor: Aina i Kemalat i Islam, 1893; Ruhani Hazain, tom 5, str. 547.","headingId":"et-teblig-prva-arapska-knjiga","headingText":"Et-teblig - prva arapska knjiga"},{"text":"Ruhani Hazain, tom 9, str. 31 Ko god dođe i ne prizna našu pobedu, jasno će se razumeti da žudi da postane potomak nezakonite veze i da nije zakonitog porekla. Izvor: Ruhani Hazain, tom 9, str. 31. Mnogo više Mirzinih navoda i njegove upotrebe prostih izraza može se pronaći ovde: Mirza Ghulam Ahmad wrote that the Quran used harsh words, thus it's ok to do so Mirza Ghulam Ahmad wrote vulgarities in Arabic also, new research from Arab ex Ahmadis","headingId":"ruhani-hazain-tom-9-str-31","headingText":"Ruhani Hazain, tom 9, str. 31"},{"text":"Mirzina kritika biblijskog Isaa U ovom tekstu Mirza Gulam Kadijani kritikuje biblijskog Isaa zato što nije postupao u skladu sa sopstvenim moralnim učenjem. Ističe da je Isa prokleo smokvu kada ju je zatekao bez ploda, iako je druge podsticao da mole. Zatim navodi da je Isa druge učio da nikoga ne nazivaju budalom, dok je sam jevrejske starešine nazivao nezakonitom decom i vređao ih u svakoj propovedi pogrdnim imenima. Mirza Gulam Ahmed tvrdi da učitelj morala mora prvo pokazati taj moral na samom sebi. Postavlja i retoričko pitanje: da li takvo manjkavo učenje, koje ni sam Isa nije sledio, može biti od Boga? Očigledna je protivrečnost u argumentu kada Mirza Gulam Ahmed kritikuje biblijskog Isaa zbog njegovog ponašanja, dok sam","headingId":"mirzina-kritika-biblijskog-isaa","headingText":"Mirzina kritika biblijskog Isaa"},{"text":"koristi slične, pa i gore izraze da bi vređao druge, a istovremeno tvrdi da je poslanik, pa čak i mesija koji svoje učenje prima od Boga. Ako učitelj morala, kakvim se Mirza smatrao, ne uspe da živi po samim načelima koja zastupa, i pritom koristi jezik i postupke koji protivreče njegovom moralnom učenju, time ne podriva samo verodostojnost svoje poruke, nego obesnažuje i tvrdnju da bi njegovo učenje moglo biti od Boga. Primena istog merila koje on postavlja drugima razotkriva slabosti njegovog sopstvenog položaja.","headingId":"mirzina-kritika-biblijskog-isaa","headingText":"Mirzina kritika biblijskog Isaa"}]},{"slug":"Ko-je-poslednji-poslanik","chunks":[{"text":"Kadijanci javno uče da posle Poslanika Muhammeda ﷺ ne može doći poslanik koji donosi zakon, ali da poslanici koji ne donose zakon mogu dolaziti uvek. Njihovi sopstveni najraniji spisi tvrde suprotno: da u ovoj zajednici može postojati samo jedan jedini poslanik, Obećani Mesija, i apsolutno niko drugi. Razlika između poslanika koji donose i onih koji ne donose zakon jeste obmana. Pravo kadijansko verovanje jeste da su vrata poslanstva zatvorena, ali da su otvorena za Mirzu Gulama Kadijanija kao izuzetak. To potvrđuje i četvrti kalifa. Kadijanci vole da tvrde da je Poslanik Muhammed ﷺ poslednji poslanik u smislu da posle njega ne može doći poslanik koji donosi zakon, poput poslanika Nuha, Ibrahima, Musaa, Isaa i Muhammeda ﷺ, ali da, prema njima,","headingId":"","headingText":""},{"text":"poslanici koji ne donose zakon i koji slede šerijat Poslanika Muhammeda ﷺ mogu dolaziti uvek. Koji god hadis im navedete u kojem je jasno rečeno da posle Poslanika Muhammeda ﷺ neće biti poslanika, oni će tvrditi da to znači da neće biti poslanika koji donosi zakon. Međutim, to nije bilo verovanje ni selefa, ni prvih naraštaja nakon Mirze Gulama Kadijanija i njegovih ranih kalifa, koji se u kadijanizmu smatraju božanski vođenima.","headingId":"","headingText":""},{"text":"Ruhani Hazain, tom 20, str. 185 Predavanje u Lahoreu U Časnom Kur'anu, pa i u većini ranijih spisa, zabeleženo je da poslednji izaslanik (ahiri mursel), koji će doći u liku Adema i koji će se zvati Mesija, nužno mora biti rođen na kraju šestog milenijuma, kao što je i Adem stvoren na kraju šestog dana. Izvor: Ruhani Hazain, tom 20, str. 185, Predavanje u Lahoreu.","headingId":"ruhani-hazain-tom-20-str-185-predavanje-u-lahoreu","headingText":"Ruhani Hazain, tom 20, str. 185 - Predavanje u Lahoreu"},{"text":"Malfuzat, tom 10, str. 363 Od Adema do Časnog Poslanika ﷺ trajao je lanac objave. Nakon toga je Uzvišeni Allah obećao da će podizati obnovitelje (mudžeddide) radi oživljavanja vere. Izvor: Malfuzat Obećanog Mesije, tom 10, str. 363, od 17. maja 1908.","headingId":"malfuzat-tom-10-str-363","headingText":"Malfuzat, tom 10, str. 363"},{"text":"Ruhani Hazain, tom 22, str. 201 Hakikatul vahj Jednoglasno je prihvaćena stvar među ehli sunnetom da je poslednji obnovitelj (mudžeddid) ovog ummeta Obećani Mesija, koji će se pojaviti u poslednjim danima. Izvor: Ruhani Hazain, tom 22, str. 201, Hakikatul vahj.","headingId":"ruhani-hazain-tom-22-str-201-hakikatul-vahj","headingText":"Ruhani Hazain, tom 22, str. 201 - Hakikatul-vahj"},{"text":"Časopis Tašhiz el azhan Tašhiz el azhan bio je časopis koji je 1906. godine u Kadijanu pokrenuo Mirza Bešir ud din Mahmud Ahmed, sin Mirze Gulama Kadijanija. Prvo izdanje objavljeno je 1. marta 1906. Mevlevi Muhammed Ali u njemu je obilno hvalio Mirzu Bešir ud dina Mahmuda Ahmeda, pa je čak podržavao i poslanstvo Mirze Gulama Ahmeda. Izgleda da je u najranijim izdanjima Tašhiz el azhana ime Mirze Bešir ud dina Mahmuda Ahmeda pisano uz dodatak sallallahu alejhi ve sellem, koji se skraćeno obeležava slovom sad. Do 1910. godine Šejh Abdur Rahman Lahori bio je sourednik zajedno sa Mirzom Bešir ud dinom Mahmudom Ahmedom, i to pre njegovog hilafeta. Do 1913. godine urednik je, po svemu sudeći, postao Kazi Muhammed","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"Zahurudin Akmal. On je, međutim, bio urednik od samog početka, a Mirza Bešir ud din je lagao i tvrdio da je on urednik. Mirza Bešir ud din jedva da je znao da čita i piše. U martu 1922. godine časopis Tašhiz el azhan spojen je sa urdu izdanjem Review of Religions. Tashhiz al Azhan was a Magazine founded by Mahmud Ahmad in 1906 U tom časopisu nalazimo sledeće: Risala Tasheezul Azhan Qadian, izdanje od 27. marta 1914. Ako je jedno nezavisno od drugog, a drugo je u potrebi za prvim, onda se utvrđuje samo jedan poslednji poslanik. Ta stvar je potpuno jasna, i ne može biti više završetaka. Kao što je pečat poslanstva jedinstven i nedeljiv, tako i pečat poslaničkog","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"niza mora biti samo jedan. Nužno je da u tom pogledu postoji samo jedan poslednji poslanik. Time je očigledno da u zajednici Poslanika Muhammeda ﷺ ne može postojati više od jednog poslanika. Časni Poslanik ﷺ najavio je dolazak samo jednog poslanika, Obećanog Mesije. Osim njega, niko nije imenovan kao poslanik ili Allahov izaslanik. Nije prorekao dolazak nijednog drugog poslanika, a rečima „Nema poslanika posle mene\" izričito je porekao dolazak bilo kojeg drugog poslanika. Ovde se postavlja pitanje: ako „Nema poslanika posle mene\" znači da posle mene neće doći nijedan poslanik, gde je onda izuzetak za Obećanog Mesiju? Izvor: Tašhiz el azhan, izdanje od 27. marta 1914. Kao što se vidi, tvrdnja da posle Poslanika Muhammeda ﷺ mogu dolaziti poslanici koji","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"ne donose zakon, samo ne oni koji ga donose, jeste obmana. Kadijansko verovanje u stvarnosti glasi da su vrata poslanstva zatvorena, ali da su otvorena za Mirzu Gulama Kadijanija kao izuzetak, jer je on tobože bio najavljen. Odgovor na to jeste da je već objašnjeno kako iz ove zajednice poslednji poslanik može biti samo onaj ko je potpuna manifestacija i savršeni odraz Poslanika ﷺ, u kome ne ostaje nikakav trag drugosti. Očigledno je da ovaj hadis, koji govori o pečatu, ne poriče postojanje onoga ko je krajnji i savršeni predstavnik. Jasno je da se niko ne može smatrati potpunim i savršenim odrazom ako u njemu postoji ikakav trag drugosti. Kao što je utvrđeno, samo jedna takva osoba može biti Obećani","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"Mesija, i to je pokazano tokom vekova. Hadis ukazuje na to da je Poslanik ﷺ rekao „Nema poslanika posle mene\" da bi isključio dve vrste ljudi: one koji su potpuno lišeni svojstava poslanstva, jer su sasvim nepovezani i tuđi, i one koji poseduju neka svojstva poslanstva, ali ne u potpunosti, jer su i oni izvan područja savršenog predstavljanja. Prema ovom hadisu, očigledno je da u ovoj zajednici može postojati samo jedan poslanik, a to je Obećani Mesija, i apsolutno niko drugi ne može doći. Osim toga, razmatranje drugih hadisa potvrđuje da je Poslanik Muhammed ﷺ poslanikom odredio samo Obećanog Mesiju i da taj naziv nije dodelio nikome drugom. Budući da će budući dolazak Mesije u svetu obnoviti svetlost Poslanikovog učenja,","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"nužno je da se on smatra istinskim naslednikom i konačnim predstavnikom Poslanika. Time je utvrđeno da će on biti i poslednji naslednik, koji obuhvata sva savršenstva i svojstva Poslanika, i da se nikakva dodatna svojstva ne mogu dodati preko onoga što on već otelovljuje. Izvor: Tašhiz el azhan.","headingId":"casopis-tashiz-el-azhan","headingText":"Časopis Tašhiz el-azhan"},{"text":"Ruhani Hazain, tom 20 Tezkiretu š šehadetejn Ali Allahov zakon je takav da se dve vrste izaslanika ne ubijaju. Prvo, oni koji dolaze na početku loze ili niza izaslanika, kao što je u Musaovoj lozi bio Musa, mir neka je na njega, a u muhammedanskom nizu naš Poslanik Muhammed ﷺ. Drugo, oni poslanici i Božiji odabranici koji dolaze na kraju loze ili niza poslanika, kao što je u Musaovom nizu bio Isa, mir neka je na njega, a u muhammedanskom nizu ovaj ponizni… Izvor: Ruhani Hazain, tom 20, Tezkiretu š šehadetejn. Izrazom „ovaj ponizni\" Mirza označava samog sebe. On, dakle, sebe smešta na kraj muhammedanskog niza, na mesto koje u Musaovom nizu pripada Isau, mir neka je na njega.","headingId":"ruhani-hazain-tom-20-tezkiretu-s-sehadetejn","headingText":"Ruhani Hazain, tom 20 - Tezkiretu-š-šehadetejn"},{"text":"Ruhani Hazain, tom 22, str. 407 Hakikatul vahj Jer da su i drugi pobožni ljudi, koji su živeli pre mene, imali isto obilje razgovora sa Allahom i da su im se otkrivale stvari iz nevidljivog sveta, onda bi i oni zasluživali da budu nazvani poslanicima. U tom slučaju bi to bio nedostatak u proročanstvu Poslanika Muhammeda ﷺ. Iz tog razloga je Allahova mudrost sprečila te čestite prethodnike da dosegnu taj blagoslov poslanstva. Kao što u verodostojnim hadisima stoji, postojaće SAMO JEDNA TAKVA OSOBA, i proročanstvo će se ispuniti. Izvor: Ruhani Hazain, tom 22, str. 407, Hakikatul vahj.","headingId":"ruhani-hazain-tom-22-str-407-hakikatul-vahj","headingText":"Ruhani Hazain, tom 22, str. 407 - Hakikatul-vahj"},{"text":"Svedočanstvo četvrtog kalife Mirza Tahir Ahmed, četvrti kalifa ahmedijske zajednice i unuk Mirze Bešir ud dina Mahmuda, izjavio je u jednom snimku da posle Mirze Gulama Ahmeda neće doći nijedan poslanik. To je suprotno verovanju koje kadijanska zajednica širi, a prema kojem poslanstvo nema kraja. Deceptions of Ahmadi Murabbis on Finality of Prophethood izjava počinje od 6:32:30","headingId":"svedocanstvo-cetvrtog-kalife","headingText":"Svedočanstvo četvrtog kalife"}]},{"slug":"Lazni-pecat-poslanika","chunks":[{"text":"U Nadahnutoj hutbi, knjizi iz 1902. godine za koju je tvrdio da ju je primio objavom, Mirza Kadijani izvodi sledeće: da je istinski pečat poslanstva određen za šesti milenijum, da je on ta poslednja cigla kojom se dovršava građevina, da je on pečat halifa ovog ummeta kao što je Isa bio poslednji u Musaovom nizu, i da se time dva niza izjednačuju. Pečat poslanstva time se ne potvrđuje na Muhammedu ﷺ, nego se prenosi na Mirzu. Izraz hatmijjet označava pečat, odnosno konačnost poslanstva. U islamu se on odnosi isključivo na Muhammeda ﷺ, koji je pečat svih poslanika.","headingId":"","headingText":""},{"text":"Istinski pečat poslanstva dat je jednookom iz Kadijana Mirza Kadijani je 1902. godine u knjizi Nadahnuta hutba, za koju je tvrdio da ju je primio objavom, rekao: Znaj da je hatmijjet od večnosti dat Muhammedu ﷺ. Zatim je on svoju dušu predao onome koga je poučio i učinio ga svojom senkom. Blago onome ko zna i uči. Istinski hatmijjet bio je određen u šestom milenijumu, koji je šesti dan od dana Svemilosnog. Izvor: Nadahnuta hutba, str. 310.","headingId":"istinski-pecat-poslanstva-dat-je-jednookom-iz-kadijana","headingText":"Istinski pečat poslanstva dat je jednookom iz Kadijana"},{"text":"Mirza Kadijani dovršio je nedovršenu građevinu islamskog poslanstva Bog je hteo da dovrši vest i da građevinu završi poslednjom ciglom. Ja sam ta cigla, o vi koji gledate. Izvor: Nadahnuta hutba, str. 178.","headingId":"mirza-kadijani-dovrsio-je-nedovrsenu-gradjevinu-islamskog-poslanstva","headingText":"Mirza Kadijani dovršio je nedovršenu građevinu islamskog poslanstva"},{"text":"Mirza Kadijani je pečat izaslanika Zatim znaj da Obećani Mesija u Božijoj Knjizi nije Isa, sin Merjemin, nosilac Jevanđelja i sluga Musaovog zakona, kako su mislili neki neznalice iz iskrivljene i zabludele skupine, nego je on pečat halifa iz ovog naroda, kao što je i Isa bio poslednji među naslednicima Musaovog lanca. Bio je poput poslednje cigle i pečat izaslanika. Izvor: Nadahnuta hutba, str. 309. I Mirza kaže: Nadam se da ću se pojaviti na kraju muhammedanskog niza, kao što se Mesih pojavio na kraju Musaovog lanca, s Božijom dozvolom, kako bi ta dva lanca bila jednaka. Izvor: Nadahnuta hutba, str. 124. A o sebi Mirza u istoj knjizi kaže: I dat mi je naziv Isaa, koji je Mesih, jer","headingId":"mirza-kadijani-je-pecat-izaslanika","headingText":"Mirza Kadijani je pečat izaslanika"},{"text":"je sa mnom zapečaćeno nasledstvo Poslanika narodâ, najboljeg od odabranih, kao što je sa Isaom bilo zapečaćeno nasledstvo Musaovog lanca. Izvor: Nadahnuta hutba, str. 324. Mirza je 1902. godine rekao i sledeće: Početak niza je naš Poslanik, poput Musaa, a pečat je poput Isaa, kako bi se Božije obećanje ispunilo istinski i stvarno. U tome je, doista, znak za ljude koji razmišljaju. Ta dva lanca trebalo je da budu jednaka: prvi kao prvi, a drugi kao drugi. Izvor: El Huda, str. 329.","headingId":"mirza-kadijani-je-pecat-izaslanika","headingText":"Mirza Kadijani je pečat izaslanika"}]},{"slug":"Mirzina-protivrecnost-o-Isau-zivom-na-nebu","chunks":[{"text":"Kadijanska optužba da su muslimani koji veruju u telesno uzdignuće Isaa, mir neka je na njega, mnogobošci ruši se čim se otvore objavljene knjige samog Mirze Gulama Ahmeda. On je upravo to verovanje zastupao i propovedao 52 godine svog života, uključujući i 12 godina svog navodnog poslanstva, pre nego što je promenio stav. Njegov sopstveni naslednik, takozvani Obećani reformator, to ranije verovanje izričito je nazvao mnogoboštvom i bezbožništvom, čime je Mirzu osudio merilom njegove sopstvene zajednice.","headingId":"","headingText":""},{"text":"Kadijanska optužba protiv muslimana Kadijanci su oduvek, i u prošlosti i danas, osuđivali muslimane koji drže da Isa, mir neka je na njega, nije umro i da je telesno uzdignut na nebo. Takve muslimane lažno i klevetnički optužuju za mnogoboštvo, za pobožanstvenjivanje Mesiha, mir neka je na njega, ili za podržavanje mnogobožačkih verovanja hrišćana. Krajnji zaključak koji sledi iz pojedinih kadijanskih spisa bio bi da svako ljudsko biće koje napusti Zemljinu atmosferu postaje bog. Ovaj tekst će iz spisa samog Mirze Gulama Ahmeda iz Kadijana, poslanika ahmedijske zajednice poznate kao kadijanska, pokazati sledeće: 1. Mirza je 52 godine svog života izjavljivao verovanje u besmrtnost Isaa Mesiha, mir neka je na njega, i u to da je on živ, u svom","headingId":"kadijanska-optuzba-protiv-muslimana","headingText":"Kadijanska optužba protiv muslimana"},{"text":"telu, na nebu. 2. Mirza je oko 12 godina svog navodnog poslanstva verovao u ono što je sam kasnije nazvao mnogobožačkim verovanjem, a što je njegov naslednik nazvao bezbožništvom, i to verovanje je i propovedao, iako je kasnije tvrdio da ga je njegov Bog poslao upravo zato da ga uništi. 3. Mirzino kasnije mišljenje o smrti Mesiha, mir neka je na njega, i dalje je Isaa smeštalo živog na nebo, u telu, i to putem Mirzinog sopstvenog učenja da duše odmah nakon smrti dobijaju nova tela.","headingId":"kadijanska-optuzba-protiv-muslimana","headingText":"Kadijanska optužba protiv muslimana"},{"text":"Mirza potvrđuje da je Isa živ na nebu Berahin i Ahmedija, 1884. Godine 1884. Mirza Gulam Ahmed je u svojoj knjizi Berahin i Ahmedija, upravo onoj za koju kadijanci danas tvrde da je porazila hrišćanstvo i utvrdila Mirzu kao obnovitelja, napisao sledeću izričitu potvrdu Isaovog uzdignuća i povratka: Poslanik Isa, mir neka je na njega, ostavio je Jevanđelje u nepotpunom obliku i bio je uzdignut na nebo, a Jevanđelje će još dugo ostati nepotpuno u rukama ljudi. Izvor: Berahin i Ahmedija, četvrti deo, str. 431, 1884. Na drugoj strani iste knjige: Kada se Isa, mir neka je na njega, ponovo vrati na ovaj svet, vera će se raširiti po svim krajevima Zemlje. Izvor: Berahin i Ahmedija, četvrti deo, str. 593,","headingId":"mirza-potvrdjuje-da-je-isa-ziv-na-nebu-berahin-i-ahmedija-1884","headingText":"Mirza potvrđuje da je Isa živ na nebu - Berahin-i Ahmedija, 1884."},{"text":"1884. Mirza u svojoj knjizi Aina i Kemalat i Islam, na str. 548, beleži i godinu u kojoj je, kako tvrdi, objava počela: Kada sam dosegao najbolje doba svog života i navršio četrdeset godina, dopro je do mene povetarac objave. Izvor: Aina i Kemalat i Islam, str. 548. Mirza je tvrdio da je objavu počeo primati oko 1879. godine, što znači da je navodnu poslaničku objavu primao sve do 1891. godine a da nijednom nije porekao niti osporio verovanje u telesno uzdignuće Isaa, dakle upravo ono verovanje koje će kasnije nazvati velikim mnogoboštvom. Već i to samo po sebi dovoljno je pobijanje njegove tvrdnje o poslanstvu. Uzvišeni Bog ne prihvata nevernstvo za Svoje robove. Kako bi onda od poslanika kojeg","headingId":"mirza-potvrdjuje-da-je-isa-ziv-na-nebu-berahin-i-ahmedija-1884","headingText":"Mirza potvrđuje da je Isa živ na nebu - Berahin-i Ahmedija, 1884."},{"text":"je poslao prihvatio veliko mnogoboštvo dvanaest godina zaredom? Godine 1902. Mirza je u knjizi Čudo Mesije, na str. 202, napisao i sledeće: I meni je objavljivano tokom jednog razdoblja, a to je razdoblje objave Pečata vjerovjesnika, od četrdesete do šezdesete godine života. Izvor: Čudo Mesije, str. 202, 1902.","headingId":"mirza-potvrdjuje-da-je-isa-ziv-na-nebu-berahin-i-ahmedija-1884","headingText":"Mirza potvrđuje da je Isa živ na nebu - Berahin-i Ahmedija, 1884."},{"text":"Kadijanska misionarska knjiga potvrđuje preokret Zvanična kadijanska misionarska knjiga Život Ahmeda, koju je objavio ogranak ahmedija u Rabvi, sadrži sledeće upečatljivo priznanje: Ahmed (Mirza Gulam Ahmed Kadijani) je u svojoj knjizi Berahin i Ahmedija, objavljenoj 1884. godine, potvrdio tradicionalno verovanje da je Mesih živ na nebu i da će se vratiti na Zemlju, videti str. 361 i 499 u trećoj fusnoti. Nije se plašio racionalnosti pred kojom se ser Sejjid Ahmed Han ranije predao. Ali 1891. godine, kada je Bog obavestio Ahmeda da je Mesih umro, tek tada je promenio svoje verovanje u vezi sa tim. Izvor: Život Ahmeda, ogranak ahmedija u Rabvi, str. 40, druga fusnota. To priznanje iz njihove sopstvene misionarske literature presudno je. Njihova zvanična publikacija potvrđuje","headingId":"kadijanska-misionarska-knjiga-potvrdjuje-preokret","headingText":"Kadijanska misionarska knjiga potvrđuje preokret"},{"text":"da je Mirza tradicionalno islamsko verovanje o Isaovom uzdignuću i povratku držao od 1884. do 1891. godine, dakle sedam godina nakon objavljivanja Berahin i Ahmedije i dvanaest godina od početka njegovog navodnog poslanstva.","headingId":"kadijanska-misionarska-knjiga-potvrdjuje-preokret","headingText":"Kadijanska misionarska knjiga potvrđuje preokret"},{"text":"Mirza osuđuje verovanje koje je držao 52 godine U knjizi Dodatak Hakikatul vahju, napisanoj 1907. godine, Mirza je na str. 660, u dvanaestom redu, napisao: Loše je ponašanje reći da Isa nije umro, a to nije ništa drugo do veliko mnogoboštvo. Izvor: Dodatak Hakikatul vahju, str. 660, 1907. Prema Mirzinim sopstvenim rečima iz 1907. godine, on je i sam bio kriv za loše ponašanje i veliko mnogoboštvo tokom prvih 52 godine svog života, i tokom prvih 12 godina svoje navodne poslaničke misije.","headingId":"mirza-osudjuje-verovanje-koje-je-drzao-52-godine","headingText":"Mirza osuđuje verovanje koje je držao 52 godine"},{"text":"Presuda drugog kalife Mirza je bio mnogobožac i bezbožnik Drugi kadijanski kalifa, u zajednici poznat kao Obećani reformator, o dostignućima svog oca Mirze napisao je sledeće: Spasio je islam od mnogoboštva i bezbožništva raširenih među muslimanima time što je dokazao da je Mesih umro prirodnom smrću. Izvor: Obećani reformator, drugi kadijanski kalifa, Merjem lomi krst, str. 170. Logična posledica izjave Obećanog reformatora neizbežna je: ako je verovanje u Isaovu besmrtnost mnogoboštvo i bezbožništvo, a Mirza je to isto verovanje držao i propovedao 52 godine svog života i 12 godina svog navodnog poslanstva, onda je Mirza Gulam Ahmed i sam bio mnogobožac i bezbožnik veći deo svog života i polovinu razdoblja svoje navodne misije. Sin je osudio oca sopstvenim perom.","headingId":"presuda-drugog-kalife-mirza-je-bio-mnogobozac-i-bezboznik","headingText":"Presuda drugog kalife - Mirza je bio mnogobožac i bezbožnik"},{"text":"Mirzino skrivanje istine deset godina Protivrečnost ide i dalje. Iako je Mirza u kasnijim spisima tvrdio da ga je Bog poslao upravo zato da ispravi verovanje o Isaovom uzdignuću, on je 1884. objavio Berahin i Ahmediju u kojoj to uzdignuće potvrđuje, i nastavio je da je objavljuje i prodaje bez ispravke sve do 1891. godine. Zatim je u jednom nadahnutom spisu ustvrdio da je još od 1881. godine, dakle deset godina pre svoje javne objave, znao da se Isa, mir neka je na njega, neće vratiti i da je on sam Obećani Mesija. Njegove sopstvene reči o tom prikrivanju zabeležene su u Aina i Kemalat i Islamu: Boga mi, odavno sam znao da sam učinjen Mesihom, sinom Merjeminim, i da","headingId":"mirzino-skrivanje-istine-deset-godina","headingText":"Mirzino skrivanje istine deset godina"},{"text":"ću boraviti u njegovoj kući, ali sam to prikrivao imajući u vidu tumačenje toga. Štaviše, nisam promenio svoje verovanje i bio sam među onima koji su ga se držali. Deset godina sam se uzdržavao od toga da to obznanim, nisam žurio niti se ubrzavao, i nisam obavestio ni voljenog ni neprijatelja, niti ikoga prisutnog. Izvor: Aina i Kemalat i Islam, str. 551, 1893. Ali Mirzin sopstveni kasniji spis izravno protivreči toj tvrdnji o prikrivanju zbog tumačenja. U knjizi Ejjamus sulh, na str. 271, napisanoj 1899. godine, kaže: U Berahin i Ahmediji sam pogrešno protumačio smrt kao ispunjenje pune nagrade, i sveštenici su to ponekad koristili protiv mene. Ali oni nemaju nikakvog opravdanja za ono što govore. Priznajem da sam pogrešio","headingId":"mirzino-skrivanje-istine-deset-godina","headingText":"Mirzino skrivanje istine deset godina"},{"text":"u tom tumačenju. Božanska objava bila je jasna, ali ja sam, kao i drugi ljudi, sklon greškama i zaboravu. Izvor: Ejjamus sulh, str. 271, 1899. Te dve izjave ne mogu obe biti istinite. U Aina i Kemalat i Islamu iz 1893. Mirza kaže da je istinu znao od 1881. godine, ali da ju je namerno prikrivao deset godina, ne žureći da je obznani. U Ejjamus sulhu iz 1899. Mirza kaže da je u svom ranijem tumačenju zaista pogrešio i da prosto nije razumeo jasnu božansku objavu. Ili je Mirza bio svesni obmanjivač koji je istinu znao i skrivao je, ili je bio poslanik koji je čitavu deceniju bio nesposoban da razume jasnu objavu od Boga. Kadijanci moraju izabrati koji od","headingId":"mirzino-skrivanje-istine-deset-godina","headingText":"Mirzino skrivanje istine deset godina"},{"text":"dva samoopisa svog poslanika prihvataju, a nijedan izbor im ne ide u prilog. Značenje toga je očigledno: Mirza je tvrdio da je objava koja mu je saopštila da je Isa umro bila jasna, a ipak je nije razumeo deset godina. Takvo je stanje čoveka kojeg kadijanci predstavljaju kao nadahnutog poslanika koji prima neposrednu poruku od Uzvišenog Boga.","headingId":"mirzino-skrivanje-istine-deset-godina","headingText":"Mirzino skrivanje istine deset godina"},{"text":"Isa živi na nebu u novom telu Mirzin konačni stav Čak i nakon Mirzinog preokreta o smrti Isaa, mir neka je na njega, njegovo učenje je i dalje Isaa smeštalo živog na nebo, sada sa novim telom umesto izvornog. U knjizi Filozofija učenja islama Mirza piše: Dušu uvek mora pratiti telo da bi svoje dužnosti obavljala kako treba. Istina je da ovo prolazno telo napušta dušu prilikom smrti, ali joj se u međusvetu ono zamenjuje jednim telom, poslednjim telom. Izvor: Filozofija učenja islama. A u knjizi Tajna hilafeta, na str. 373, Mirza piše o stanju umrlih poslanika: Bog otvara oko umrlog poslanika koji je bio poslat tim ljudima, pa on upravlja pogled ka njima kao da se probudio iz sna","headingId":"isa-zivi-na-nebu-u-novom-telu-mirzin-konacni-stav","headingText":"Isa živi na nebu u novom telu - Mirzin konačni stav"},{"text":"i zatiče među njima veliku nepravdu i pokvarenost. Izvor: Tajna hilafeta, str. 373. Na sledećoj strani dodaje: Ovo je silazak Isaa oko kojeg se oni razilaze. Izvor: Tajna hilafeta, str. 374. Suština Mirzinog konačnog stava je, dakle, sledeća: nakon što je Isa, mir neka je na njega, umro, dato mu je novo telo na nebu, telo drugačije prirode od zemaljskog, ali ipak telo. Na nebu Isa spava, budi se, otvara oči i posmatra stanje svog naroda. To, prema Mirzi, nije pobožanstvenjivanje Mesiha. Prema Mirzinom sopstvenom konačnom učenju, Isa je prisutan na nebu u posebnom nadtelu, spava i budi se i posmatra stanje svog naroda, i to nije mnogoboštvo. Ali mišljenje onih muslimana koji kažu da je Isa prisutan na nebu","headingId":"isa-zivi-na-nebu-u-novom-telu-mirzin-konacni-stav","headingText":"Isa živi na nebu u novom telu - Mirzin konačni stav"},{"text":"sa običnim ljudskim telom jeste mnogoboštvo i bezbožništvo. Nedoslednost je potpuna. Mirza i sam završava sa Isaom živim na nebu, u telu koje mu je dato nakon smrti, telu sposobnom da spava, da se budi i da posmatra poslove živih, i to proglašava ispravnim verovanjem. U isto vreme muslimani koji potvrđuju Isaovo prisustvo na nebu sa njegovim izvornim telom nazivaju se mnogobošcima. Mirzino sopstveno učenje više ide u prilog hrišćanskom učenju o vaskrsnom telu nego islamskom učenju koje je navodno branio. Vredi napomenuti da i sami hrišćani tvrde da se Isa, mir neka je na njega, nakon što je umro, ukazao svojim učenicima u svetlosnom telu drugačijem od zemaljskog, i da je potom uzdignut na nebo, gde ostaje živ i","headingId":"isa-zivi-na-nebu-u-novom-telu-mirzin-konacni-stav","headingText":"Isa živi na nebu u novom telu - Mirzin konačni stav"},{"text":"svestan stanja svog naroda. Mišljenje koje se u tome poklapa sa verovanjima hrišćana, prema ovom poređenju, jeste konačna izjava Mirze Gulama Ahmeda, a ne mišljenje bilo kojeg muslimanskog učenjaka.","headingId":"isa-zivi-na-nebu-u-novom-telu-mirzin-konacni-stav","headingText":"Isa živi na nebu u novom telu - Mirzin konačni stav"},{"text":"Protivrečnost sa Kur'anom Mirzina tvrdnja da Isa, mir neka je na njega, nakon svoje smrti posmatra stanje svog naroda protivreči jasnoj izjavi Kur'ana. Uzvišeni Bog navodi šta će Isa reći na Sudnjem danu: Sura El Maida 5:117 Ja sam im samo govorio ono što si im Ti naredio: „Obožavajte Allaha, i mog i vašeg Gospodara!“ I ja sam bio njima svedok dok sam bio među njima, a kad si me Ti k Sebi uzeo, Ti si ih jedini nadzirao; Ti nad svime nadzireš.\" Mirza je i sam priznao ovu kur'ansku protivrečnost. U knjizi Dodatak Hakikatul vahju, na str. 666, napisao je da bi Isa, mir neka je na njega, bio lažov, sačuvaj Bože, ako bi znao za dela svog naroda","headingId":"protivrecnost-sa-kuranom","headingText":"Protivrečnost sa Kur'anom"},{"text":"nakon svoje smrti. A ipak, Mirzino sopstveno učenje u Tajni hilafeta čini da Isa radi upravo to: da se budi na nebu i posmatra stanje svog naroda. Mirza je unutar sopstvenih knjiga protivrečio sopstvenom kur'anskom argumentu.","headingId":"protivrecnost-sa-kuranom","headingText":"Protivrečnost sa Kur'anom"},{"text":"Zaključak šta utvrđuju Mirzine sopstvene knjige Iz objavljenih spisa samog Mirze Gulama Ahmeda nesporno se utvrđuje sledeće. 1. Mirza je potvrđivao telesno uzdignuće Isaa i njegov povratak na Zemlju tokom 52 godine svog života i 12 godina svog navodnog poslanstva. 2. Njihova sopstvena zvanična misionarska publikacija to otvoreno potvrđuje. 3. Kada je Mirza 1891. godine promenio stav, njegov sopstveni naslednik, Obećani reformator, ranije verovanje proglasio je mnogoboštvom i bezbožništvom, čime je osudio samog Mirzu. 4. Mirza je dao dva međusobno protivrečna objašnjenja tog preokreta: u jednom kaže da je istinu znao deset godina i namerno je prikrivao, a u drugom da je jednostavno pogrešio i da nije razumeo jasnu objavu. 5. Čak i Mirzin konačni stav i dalje smešta Isaa","headingId":"zakljucak-sta-utvrdjuju-mirzine-sopstvene-knjige","headingText":"Zaključak - šta utvrđuju Mirzine sopstvene knjige"},{"text":"živog na nebo u novom telu, gde spava, budi se i posmatra svoj narod, što protivreči kur'anskom svedočanstvu o onome što će Isa reći na Sudnjem danu, kako je i sam Mirza priznao. Kadijanska optužba za mnogoboštvo protiv muslimana koji veruju u uzdignuće Isaa jeste optužba koju je pero Mirze Gulama Ahmeda prvo ispisalo protiv samog Mirze Gulama Ahmeda.","headingId":"zakljucak-sta-utvrdjuju-mirzine-sopstvene-knjige","headingText":"Zaključak - šta utvrđuju Mirzine sopstvene knjige"}]},{"slug":"Neispunjena-prorocanstva-Mirze-Gulama-Kadijanija","chunks":[{"text":"Merilo nije postavio niko od Mirzinih protivnika, nego on sam: njegova proročanstva su jedini ispit njegove istinitosti. U objavi od 5. novembra 1907. navodi objavu „Produžiću i tvoje dane\" i objašnjava je rečima da će oni koji tvrde da mu je nakon jula 1907. preostalo još samo četrnaest meseci života biti osramoćeni. Umro je deset meseci kasnije, u maju 1908. Po njegovim sopstvenim rečima, ispasti lažov u sopstvenom proročanstvu jeste najveća sramota od svih sramota. Najjednostavnije pobijanje kadijanske religije jeste ispitivanje neispunjenih proročanstava Mirze Gulama Kadijanija. To merilo nije nametnuto spolja. Postavio ga je on lično.","headingId":"","headingText":""},{"text":"Merilo koje je Mirza sam postavio Da bi se prosudila moja istinitost ili laž, ne postoji bolji ispit od mojih proročanstava. Izvor: Ruhani Hazain, tom 19, str. 288. Neka bude poznato onima koji ne veruju da će moja istinitost ili lažnost biti prosuđena mojim proročanstvima. Za to ne postoji nijedan drugi kamen kušnje. Izvor: Pamflet od 10. jula 1888; Aina i Kemalat i Islam, str. 288. Nije moguće da proročanstva poslanika kasne. Izvor: Ruhani Hazain, tom 19, str. 5. Ispasti lažov u sopstvenom proročanstvu najveća je sramota od svih sramota. Izvor: Ruhani Hazain, tom 15, str. 382. Iako postoji više poznatih neispunjenih proročanstava Mirze Gulama Kadijanija, po njegovom sopstvenom merilu dovoljno je jedno jedino neispunjeno proročanstvo da bi se dokazalo","headingId":"merilo-koje-je-mirza-sam-postavio","headingText":"Merilo koje je Mirza sam postavio"},{"text":"da nije bio u pravu.","headingId":"merilo-koje-je-mirza-sam-postavio","headingText":"Merilo koje je Mirza sam postavio"},{"text":"Kako kadijanci odgovaraju primer Meke i Medine Kadijanci, razume se, ta proročanstva ne smatraju neuspelima, pa im menjaju značenje, izvrću ih ili ih proglašavaju metaforičnim. Primer je Mirzina izjava: Umreću ili u Meki ili u Medini. Izvor: Tezkira (Tadhkira), str. 591. Mirza je umro u Lahoreu, u današnjem Pakistanu, i za čitavog svog života nije kročio ni u Meku ni u Medinu. To očigledno pokazuje da je njegova izjava neistinita, a to je, prema njegovim sopstvenim rečima, najveća sramota od svih sramota. Kadijanci to ipak tumače tako da znači da će „umreti pobedom kakva je bila pobeda Meke i Medine\", što se iz samog proročanstva nikako ne može zaključiti. Čak i kada bi se takvo tumačenje prihvatilo, Mirzina smrt se","headingId":"kako-kadijanci-odgovaraju-primer-meke-i-medine","headingText":"Kako kadijanci odgovaraju - primer Meke i Medine"},{"text":"ni na koji način ne može nazvati pobedom. U poslednjim trenucima nije bio u stanju da govori niti da komunicira, više puta je gubio svest i na kraju je umro iscrpljen, nakon niza napada proliva u sopstvenoj postelji, kako to potvrđuju kadijanski izvori i svedočanstva očevidaca njegove smrti.","headingId":"kako-kadijanci-odgovaraju-primer-meke-i-medine","headingText":"Kako kadijanci odgovaraju - primer Meke i Medine"},{"text":"Neoboriv primer neispunjenog proročanstva Postoji, međutim, dovoljno neispunjenih proročanstava koja su neoboriva i oslobođena svakog „metaforičnog tumačenja\", bez razumnog i opravdanog odgovora. Prema ranijim izjavama samog Mirze Gulama, potrebno je samo jedno neispunjeno proročanstvo da bi se oborila nečija tvrdnja o poslanstvu. U objavi od 5. novembra 1907. Mirza navodi sledeću objavu koju tvrdi da je primio: Produžiću i tvoje dane. Zatim tu objavu i objašnjava: Ovo znači da će svi oni moji neprijatelji koji govore da mi je nakon jula 1907. preostalo još samo četrnaest meseci života, ili koji proriču moju smrt u određenom roku, biti osramoćeni, i da će Bog produžiti moje dane kako bi pokazao da je On Bog i da je sve pod Njegovom vlašću… Izvor:","headingId":"neoboriv-primer-neispunjenog-prorocanstva","headingText":"Neoboriv primer neispunjenog proročanstva"},{"text":"Tezkira, str. 978 i 980. Razložimo to na delove: 1. Pojedini protivnici su prorekli da će Mirza umreti u određenom roku, a neki od njih su tvrdili da će umreti u roku od četrnaest meseci nakon jula 1907. 2. To znači da su tvrdili da će Mirza umreti pre septembra 1908. 3. Mirza je rekao da će oni biti osramoćeni i da će Allah produžiti njegov život, jer je, kako tvrdi, primio objavu o tome. 4. Mirza je umro deset meseci kasnije, u maju 1908.","headingId":"neoboriv-primer-neispunjenog-prorocanstva","headingText":"Neoboriv primer neispunjenog proročanstva"},{"text":"Neuspeli pokušaj pobijanja od strane kadijanaca Najnovije izdanje Tezkire sadrži fusnotu Mirze Bašira Ahmeda o tome kako je ovo proročanstvo ipak ispunjeno. Ta fusnota se ovde ne navodi jer se proteže na tri stranice. Teško je poverovati da bi iko ko drži do zdravog razuma ozbiljno prihvatio izgovore iznesene u njoj. Osim toga, upućivanja iz tih fusnota više se ne mogu proveriti u izvornoj građi. Nema nijednog razloga da neko ko nije ahmedija veruje bilo čemu što je napisao Mirza Bašir Ahmed bez čvrstih uputa na dostupne izvore. Kadijanci će tvrditi da je druga strana kasnije promenila svoje proročanstvo i navela drugi datum, 4. avgust 1908, na koji Mirza Gulam nije umro, iako je prvobitno prorekla njegovu smrt u roku","headingId":"neuspeli-pokusaj-pobijanja-od-strane-kadijanaca","headingText":"Neuspeli pokušaj pobijanja od strane kadijanaca"},{"text":"od četrnaest meseci. Iz toga zaključuju da dr Abdul Hakim Han nije uspeo u svom proročanstvu, jer Mirza Gulam nije umro 4. avgusta 1908. Bilo bi nerazumno vezivati Obećanog Mesiju za proročanstvo koje je onaj ko ga je izrekao sam izmenio i dopunio. Jedino što je Bog objavio bilo je „Produžiću tvoje dane\", što je Obećani Mesija shvatio kao odgovor na prvobitno proročanstvo dr Abdul Hakim Hana, a to je proročanstvo sam doktor poništio. Ne možete nečije tumačenje, dato u određenom trenutku i u određenim okolnostima, vezati kao apsolutno za predviđanje koje je poništeno. Pošto je promenio svoje proročanstvo, logično je proveriti da li je Obećani Mesija umro 4. avgusta ili nije. Obećani Mesija nije umro 4. avgusta. Dakle, proročanstvo","headingId":"neuspeli-pokusaj-pobijanja-od-strane-kadijanaca","headingText":"Neuspeli pokušaj pobijanja od strane kadijanaca"},{"text":"dr Abdul Hakim Hana pokazalo se lažnim. To je potpuno nebitno i nije odgovor na činjenicu da je proročanstvo ostalo neispunjeno. Na poslednjoj od te tri stranice, na strani 1010, Mirza iznosi završnu izjavu: Ovo znači da će svi oni moji neprijatelji koji govore da mi je nakon jula 1907. preostalo još samo četrnaest meseci života, ili koji proriču moju smrt u određenom roku, biti osramoćeni, i da će Bog produžiti moje dane kako bi pokazao da je On Bog i da je sve pod Njegovom vlašću… Mirza Gulam naglašava da „neće umreti u roku od četrnaest meseci\", da će njegov „život biti duži od tih četrnaest meseci\" i da je to sredstvo kojim „Bog pokazuje Svoju vlast nad svime\".","headingId":"neuspeli-pokusaj-pobijanja-od-strane-kadijanaca","headingText":"Neuspeli pokušaj pobijanja od strane kadijanaca"},{"text":"Činjenica je da je Mirza umro unutar tih četrnaest meseci, bez obzira na to da li se uzme prvi datum koji je naveo Abdul Hakim, dakle pre 1. septembra 1908, ili drugi datum, 4. avgust 1908. Oba su unutar roka od četrnaest meseci na koji je Mirza odgovorio „objavom\" da će Bog „produžiti njegove dane\" i da „neće umreti u roku od četrnaest meseci\". Mirzini dani, dakle, nisu bili produženi preko četrnaest meseci. Čak i ako se insistira na tome da je Abdul Hakim promenio svoje proročanstvo na 4. avgust, a da Mirza tog dana nije umro, to ništa ne menja: Allah nema nikakve potrebe da ispuni proročanstvo još jednog čoveka koji, poput Mirze, tvrdi da prima objavu, niti da","headingId":"neuspeli-pokusaj-pobijanja-od-strane-kadijanaca","headingText":"Neuspeli pokušaj pobijanja od strane kadijanaca"},{"text":"ga time prikaže kao poslanika. Naprotiv, u tome je jedna od Allahovih mudrosti, jer je učinio da propadnu oba proročanstva, i Mirze Gulama i Abdul Hakima.","headingId":"neuspeli-pokusaj-pobijanja-od-strane-kadijanaca","headingText":"Neuspeli pokušaj pobijanja od strane kadijanaca"},{"text":"Allah je odjednom razotkrio dva lažna proroka 1. Mirza je prorekao da će živeti duže od 1. septembra 1908, a umro je pre 1. septembra 1908. Njegovo proročanstvo je propalo. 2. Abdul Hakim je izmenio svoje proročanstvo tvrdeći da će Mirza umreti 4. avgusta 1908, a Mirza je umro pre 4. avgusta 1908. Njegovo proročanstvo je propalo.","headingId":"allah-je-odjednom-razotkrio-dva-lazna-proroka","headingText":"Allah je odjednom razotkrio dva lažna proroka"}]},{"slug":"Protivrecnosti-Mirze-Gulama-Kadijanija","chunks":[{"text":"Mirza Gulam Kadijani poriče da će se Mehdi pojaviti iz potomstva Fatime, radijallahu anha, a zatim tvrdi da mu je Bog rekao da je on njen potomak. Ukida oružani džihad u vreme kolonijalne vlasti, pokornost britanskoj vlasti proglašava delom vere, a mesijanski mir najavljen u objavi vidi ostvarenim u toj istoj vlasti. Vređa ashabe zbog verovanja da je Isa živ, a na kraju sebe stavlja iznad Poslanika ﷺ tvrdeći da je njegova duhovnost bila nepotpuna. Svaka od tih tvrdnji potiče iz njegovih sopstvenih spisa. Ono što sledi zbirka je Mirzinih sopstvenih navoda, poređanih tako da se vidi kako jedan drugom protivreče.","headingId":"","headingText":""},{"text":"Mehdi iz Fatiminog potomstva Mirza Gulam Ahmed: Nijedan Mehdi se neće pojaviti među decom Fatime, radijallahu anha. Svi hadisi koji ukazuju na taj pojam su izmišljeni. Isti Mirza Gulam Ahmed: Bog mi je rekao da sam potomak Fatime, radijallahu anha, po lozi svoje majke.","headingId":"mehdi-iz-fatiminog-potomstva","headingText":"Mehdi iz Fatiminog potomstva"},{"text":"Ukidanje oružanog džihada Ukidanje oružanog džihada, kako bi se ugodilo kolonijalnim gospodarima, bila je jedna od glavnih misija lažnih poslanika koji su se pojavili nakon Muhammeda ﷺ. I Bahaullah i Mirza Gulam Ahmed tvrdili su da je oružani džihad ukinut u njihovo vreme.","headingId":"ukidanje-oruzanog-dzihada","headingText":"Ukidanje oružanog džihada"},{"text":"Deset hiljada mesija Mirza Gulam Ahmed nije samo naveo da je dolazak mesije nakon njega već određen, nego je spomenuo i mogućnost pojave deset hiljada mesija, od kojih bi neko sasvim moguće ispunio i pojedine DOSLOVNE reči hadisa koje je Mirza uvek pretvarao u metaforu da bi odgovarale njemu.","headingId":"deset-hiljada-mesija","headingText":"Deset hiljada mesija"},{"text":"Pokornost britanskoj vlasti kao deo vere Prema Mirzi Gulamu Ahmedu, pokornost britanskoj vlasti u njegovo vreme bila je deo islamskog verovanja, a pobuna protiv nje bila je jednaka pobuni protiv islama, Allaha i Njegovog Poslanika ﷺ.","headingId":"pokornost-britanskoj-vlasti-kao-deo-vere","headingText":"Pokornost britanskoj vlasti kao deo vere"},{"text":"Mesijanski mir ostvaren britanskom vlašću Poznato je judeo hrišćansko i islamsko shvatanje da će pod vlašću Mesije nastupiti veliki mir, takav mir da će vuk i ovca zajedno spavati, a dete će se igrati sa zmijom bez ikakve štete. Prema Mirzi Gulamu Ahmedu, to je ispunjeno nevernom britanskom vlašću. Istinski Allahov poslanik naspram istinskog dedžala.","headingId":"mesijanski-mir-ostvaren-britanskom-vlascu","headingText":"Mesijanski mir ostvaren britanskom vlašću"},{"text":"Vređanje ashaba Mirza Gulam Ahmed, neka su na njega Allahova prokletstva, vređao je Poslanikove ﷺ ashabe zato što su verovali da je Isa ﷺ živ i da će se vratiti. Ebu Hurejru, radijallahu anhu, opisao je kao naivnu osobu slabog razumevanja i znanja, i optužio ga da je svoja verovanja o Isau ﷺ preuzeo od tadašnjih hrišćana.","headingId":"vredjanje-ashaba","headingText":"Vređanje ashaba"},{"text":"Rafidijske sklonosti Ovde vidimo kako Mirza Gulam Ahmed iskazuje svoje rafidijske sklonosti nazivajući Ebu Hurejru, radijallahu anhu, čovekom slabog razumevanja i optužujući ga da ima pojednostavljeno viđenje islama i da pati od slabog razuma. Zašto? Zato što je zastupao uobičajeno verovanje da je Isa živ.","headingId":"rafidijske-sklonosti","headingText":"Rafidijske sklonosti"},{"text":"Skriveno i otkriveno verovanje Mirza Gulam Ahmed: Allah nije sakrio nijedan od uslova nužnih verovanja. Isti Mirza Gulam Ahmed: Allah je vekovima skrivao stvarnost drugog dolaska Isaa ﷺ, i to do te mere da je ni sam Mirza nije potpuno shvatio ni nakon svojih prvih „objava\" koje su mu govorile da je on Obećani Mesija.","headingId":"skriveno-i-otkriveno-verovanje","headingText":"Skriveno i otkriveno verovanje"},{"text":"Odnos prema kraljici Viktoriji Mirza Gulam Ahmed se dobrovoljno ponizio, podržao svoje kolonijalne gospodare protiv muslimana i izvrnuo islamska verovanja da bi ugodio Viktoriji, sve do tvrdnje da je Muhammed ﷺ prorekao mir i pravdu njene vladavine. Uporedimo kako se Muhammed ﷺ obratio Iraklijusu, vizantijskom caru, sa načinom na koji se Mirza obraćao svojoj kraljici Viktoriji. Reč je o prvorazrednom primeru toga kako je Mirza „slomio krst\": ulagivanjem „Njenom veličanstvu\" kraljici Viktoriji i moljakanjem za njeno odobrenje.","headingId":"odnos-prema-kraljici-viktoriji","headingText":"Odnos prema kraljici Viktoriji"},{"text":"Uzdizanje iznad Poslanika ﷺ Prema Mirzi Gulamu Ahmedu, neka su na njega Allahova prokletstva, duhovnost Muhammeda ﷺ bila je nepotpuna, a upotpunjena je dolaskom Mirze, jer je njegova duhovnost bila jača, snažnija i potpunija od duhovnosti Muhammeda ﷺ. Još jedan primer u kojem Mirza Gulam Ahmed sebi daje viši položaj od Muhammeda ﷺ. Prema njemu, dolazak Muhammeda ﷺ nije bio dovoljan čovečanstvu, pa je zato bio potreban i njegov sopstveni dolazak.","headingId":"uzdizanje-iznad-poslanika-","headingText":"Uzdizanje iznad Poslanika ﷺ"}]}];
